    parse_tres_gpus,
)

from .conftest import CLEAN, MESSY


def make_fields(**overrides):
    base = {
        "JobID": "12345",
        "User": "alice",
        "Partition": "gpu",
        "State": "COMPLETED",
        "Submit": "2026-06-01T08:00:00",
        "Start": "2026-06-01T09:00:00",
        "End": "2026-06-01T10:00:00",
        "Elapsed": "01:00:00",
        "AllocCPUS": "8",
        "AllocTRES": "cpu=8,mem=64G,gres/gpu=2",
        "ExitCode": "0:0",
    }
    base.update(overrides)
    return [base[name] for name in HEADER_FIELDS]


class TestElapsed:
    def test_plain(self):
        assert parse_elapsed("01:30:00") == 5400

    def test_with_day_component(self):
        assert parse_elapsed("2-12:00:00") == 2 * 86400 + 12 * 3600

    def test_single_day(self):
        assert parse_elapsed("1-00:00:30") == 86400 + 30

    def test_zero(self):
        assert parse_elapsed("00:00:00") == 0

    @pytest.mark.parametrize("bad", ["12:99", "1:2", "", "garbage", "01:60:00", "-01:00:00"])
    def test_malformed(self, bad):
        with pytest.raises(MalformedRowError):
            parse_elapsed(bad)


class TestTres:
    def test_plain_gpu(self):
        assert parse_tres_gpus("cpu=8,mem=64G,gres/gpu=2") == 2

    def test_no_gpu(self):
        assert parse_tres_gpus("cpu=4,mem=16G") == 0

    def test_empty(self):
        assert parse_tres_gpus("") == 0

    def test_typed_gpu(self):
        assert parse_tres_gpus("cpu=8,mem=64G,gres/gpu:a100=4") == 4

    def test_multiple_gres_entries_only_counts_gpus(self):
        assert parse_tres_gpus("cpu=16,mem=128G,gres/gpu=2,gres/shard=8") == 2

    def test_plain_and_typed_gpus_are_summed(self):
        assert parse_tres_gpus("cpu=8,gres/gpu=1,gres/gpu:h100=2") == 3

    def test_gpu_prefix_lookalike_ignored(self):
        assert parse_tres_gpus("cpu=8,gres/gpumem=4G") == 0

    def test_bad_gpu_count(self):
        with pytest.raises(MalformedRowError):
            parse_tres_gpus("gres/gpu=two")


class TestTimestamps:
    def test_unknown_is_none(self):
        assert parse_timestamp("Unknown") is None

    def test_valid(self):
        assert parse_timestamp("2026-06-01T08:00:00") == "2026-06-01T08:00:00"

    def test_invalid(self):
        with pytest.raises(MalformedRowError):
            parse_timestamp("yesterday")


class TestStepFiltering:
    @pytest.mark.parametrize("jid", ["12345.batch", "12345.0", "12345.extern"])
    def test_is_step(self, jid):
        assert is_step(jid)

    def test_top_level_is_not_step(self):
        assert not is_step("12345")

    def test_parse_row_returns_none_for_steps(self):
        assert parse_row(make_fields(JobID="12345.batch")) is None

    def test_clean_fixture_steps_excluded(self):
        result = parse_file(CLEAN)
        assert result.steps_skipped == 6
        assert len(result.records) == 50
        assert all("." not in r.job_id for r in result.records)


class TestParseRow:
    def test_valid_row(self):
        rec = parse_row(make_fields())
        assert rec.job_id == "12345"
        assert rec.gpus == 2
        assert rec.elapsed_sec == 3600

    def test_wrong_field_count(self):
        with pytest.raises(MalformedRowError):
            parse_row(["12345", "alice", "gpu", "COMPLETED"])

    def test_bad_alloc_cpus(self):
        with pytest.raises(MalformedRowError):
            parse_row(make_fields(AllocCPUS="eight"))

    def test_cancelled_by_uid_normalized(self):
        rec = parse_row(make_fields(State="CANCELLED by 1234"))

